mapper.select:
SELECT s.deviceId, d.deviceName, s.roleId, r.roleName, s.sessionId, s.lastMessageTimestamp, s.summary, s.promptTokens, s.completionTokens, s.createTime FROM sys_summary s LEFT JOIN sys_device d ON s.deviceId = d.deviceId LEFT JOIN sys_role r ON s.roleId = r.roleId
s.deviceId = #{deviceId}
d.userId = #{userId}
AND s.roleId = #{roleId}
ORDER BY s.createTime DESC
